// Validate banner data from webhook
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const errors = [];

  // Required fields validation
  const requiredFields = ['fullName', 'email', 'professionalTitle', 'industry', 'bannerStyle', 'keyMessage'];

  for (const field of requiredFields) {
    if (!data[field] || data[field].toString().trim() === '') {
      errors.push(`Missing required field: ${field}`);
    }
  }

  // Email format validation
  if (data.email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(data.email)) {
      errors.push('Invalid email format');
    }
  }

  // Hex color code validation (if color fields are present)
  const colorFields = ['primaryColor', 'secondaryColor', 'backgroundColor'];
  const hexRegex = /^#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})$/;

  for (const colorField of colorFields) {
    if (data[colorField] && !hexRegex.test(data[colorField])) {
      errors.push(`Invalid hex color code for ${colorField}`);
    }
  }

  // Build result object
  const result = {
    isValid: errors.length === 0,
    errorMessage: errors.length > 0 ? errors.join('; ') : '',
    validated_data: {
      fullName: data.fullName || '',
      email: data.email || '',
      professionalTitle: data.professionalTitle || '',
      industry: data.industry || '',
      bannerStyle: data.bannerStyle || '',
      keyMessage: data.keyMessage || '',
      primaryColor: data.primaryColor || '',
      secondaryColor: data.secondaryColor || '',
      backgroundColor: data.backgroundColor || '',
      additionalInfo: data.additionalInfo || ''
    }
  };

  results.push(result);
}

return results;

// Get user data from Airtable node
const userData = $('Get User from Airtable').first().json;

// Get request data from webhook
const requestData = $('Webhook Trigger').first().json.body;

// Extract user plan and usage information
const planType = userData['Plan Type'] || 'Starter';
const bannersUsedThisMonth = userData['Banners Used This Month'] || 0;
const bannersMonthlyLimit = userData['Banners Monthly Limit'] || 3;
const currentMonthStored = userData['Current Month'] || '';

// Get current month in YYYY-MM format
const now = new Date();
const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

// Check if month has changed (needs reset)
const needsReset = currentMonthStored !== currentMonth;

// Calculate number of variations from request
const numberOfVariations = parseInt(requestData.numberOfVariations) || 1;

// Determine if usage is allowed
let allowed = false;
let reason = '';

// Pro plan has unlimited access
if (planType === 'Pro') {
  allowed = true;
  reason = 'Pro plan - unlimited access';
} else {
  // For Starter or other plans, check limits
  const effectiveUsage = needsReset ? 0 : bannersUsedThisMonth;
  const newTotal = effectiveUsage + numberOfVariations;

  if (newTotal <= bannersMonthlyLimit) {
    allowed = true;
    reason = `Within monthly limit (${newTotal}/${bannersMonthlyLimit})`;
  } else {
    allowed = false;
    reason = `Monthly limit exceeded (${newTotal}/${bannersMonthlyLimit}). Upgrade to Pro for unlimited access.`;
  }
}

// Return the result object
return [{
  json: {
    allowed: allowed,
    needs_reset: needsReset,
    reason: reason,
    service_selection: 'banner',
    number_of_variations: numberOfVariations,
    current_month: currentMonth,
    plan_type: planType,
    current_usage: needsReset ? 0 : bannersUsedThisMonth,
    monthly_limit: bannersMonthlyLimit
  }
}];

// Use runOnceForAllItems - process all items
const items = $input.all();

return items.map(item => {
  const webhookBody = $('Webhook Trigger').first().json.body;
  const bannerProfile = {
    fullName: webhookBody.fullName || '',
    professionalTitle: webhookBody.professionalTitle || '',
    industry: webhookBody.industry || '',
    industryNiche: webhookBody.industryNiche || '',
    keyMessage: webhookBody.keyMessage || '',
    brandKeywords: webhookBody.brandKeywords || '',
    contentPillars: [
      webhookBody.contentPillar1 || '',
      webhookBody.contentPillar2 || '',
      webhookBody.contentPillar3 || ''
    ].filter(pillar => pillar !== ''),
    bannerStyle: webhookBody.bannerStyle || '',
    colors: {
      primary: webhookBody.primaryColor || '',
      secondary: webhookBody.secondaryColor || ''
    },
    bannerFormat: webhookBody.bannerFormat || '',
    companyLogoUrl: webhookBody.companyLogoUrl || '',
    professionalPhotoUrl: webhookBody.professionalPhotoUrl || ''
  };
  const variations = parseInt(webhookBody.numberOfVariations || 1, 10);
  return {
    json: {
      banner_profile: bannerProfile,
      email: webhookBody.email || '',
      user_name: webhookBody.fullName || '',
      variations: variations,
      original_data: webhookBody
    }
  };
});

// Get data from previous nodes
const prepareBannerData = $("Prepare Banner Data").first().json;
const recipientEmail = prepareBannerData.email || '';
const recipientName = prepareBannerData.user_name || '';
const bannerProfile = prepareBannerData.banner_profile || {};

// Get aggregated banner URLs from ImgBB
const aggregatedData = $("Aggregate Banner URLs").first().json;
const bannerUrls = aggregatedData.banner_urls || [];

// Build variations HTML using ImgBB URLs
let variationsHtml = '';
for (let i = 0; i < bannerUrls.length; i++) {
  const bannerUrl = bannerUrls[i];
  variationsHtml += `
    <div style="margin-bottom: 30px; padding: 20px; background-color: #f9f9f9; border-radius: 8px;">
      <h3 style="color: #0077b5; margin-bottom: 15px;">Variation ${i + 1}</h3>
      <div style="margin-bottom: 15px;">
        <a href="${bannerUrl}" target="_blank">
          <img src="${bannerUrl}" alt="Banner Variation ${i + 1}" style="max-width: 100%; height: auto; border-radius: 4px; box-shadow: 0 2px 8px rgba(0,0,0,0.1);" />
        </a>
      </div>
      <p style="color: #666; font-size: 14px;">
        <a href="${bannerUrl}" target="_blank" style="color: #0077b5; text-decoration: none; font-weight: bold;">Click here to view full size and download</a>
      </p>
    </div>
  `;
}

// Build banner specs section
const specsHtml = `
  <div style="margin: 30px 0; padding: 20px; background-color: #f0f8ff; border-left: 4px solid #0077b5; border-radius: 4px;">
    <h3 style="color: #0077b5; margin-bottom: 15px;">Your Banner Specifications</h3>
    <ul style="list-style: none; padding: 0; margin: 0;">
      <li style="margin-bottom: 10px;"><strong>Style:</strong> ${bannerProfile.bannerStyle || 'N/A'}</li>
      <li style="margin-bottom: 10px;"><strong>Primary Color:</strong> <span style="display: inline-block; width: 20px; height: 20px; background-color: ${bannerProfile.colors?.primary || '#000'}; border: 1px solid #ccc; vertical-align: middle; margin-right: 5px;"></span>${bannerProfile.colors?.primary || 'N/A'}</li>
      <li style="margin-bottom: 10px;"><strong>Secondary Color:</strong> <span style="display: inline-block; width: 20px; height: 20px; background-color: ${bannerProfile.colors?.secondary || '#000'}; border: 1px solid #ccc; vertical-align: middle; margin-right: 5px;"></span>${bannerProfile.colors?.secondary || 'N/A'}</li>
      <li style="margin-bottom: 10px;"><strong>Format:</strong> ${bannerProfile.bannerFormat || 'N/A'}</li>
      <li style="margin-bottom: 10px;"><strong>Key Message:</strong> ${bannerProfile.keyMessage || 'N/A'}</li>
    </ul>
  </div>
`;

// Build tips section
const tipsHtml = `
  <div style="margin: 30px 0; padding: 20px; background-color: #fff9e6; border-left: 4px solid #ffa500; border-radius: 4px;">
    <h3 style="color: #ff8c00; margin-bottom: 15px;">Tips for Using Your LinkedIn Banner</h3>
    <ul style="line-height: 1.8; color: #333;">
      <li>LinkedIn banner dimensions are 1584 x 396 pixels - your banners are optimized for this size</li>
      <li>Make sure your banner looks good on both desktop and mobile devices</li>
      <li>Update your banner regularly to keep your profile fresh and engaging</li>
      <li>Ensure your banner complements your profile photo and doesn't overlap with it</li>
      <li>Use your banner to communicate your professional brand and value proposition</li>
      <li>Test different variations to see which one resonates best with your audience</li>
    </ul>
  </div>
`;

// Build footer
const footerHtml = `
  <div style="margin-top: 40px; padding-top: 20px; border-top: 2px solid #e0e0e0; text-align: center; color: #666;">
    <p style="margin-bottom: 10px; font-size: 14px;">Created with <strong style="color: #0077b5;">Standout4Growth</strong></p>
    <p style="margin-bottom: 10px; font-size: 12px;">Empowering professionals to stand out on LinkedIn</p>
    <p style="font-size: 12px; color: #999;">Need help? Contact us at support@standout4growth.com</p>
  </div>
`;

// Build complete email HTML
const emailHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Your LinkedIn Banners Are Ready</title>
</head>
<body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 800px; margin: 0 auto; padding: 20px;">
  <div style="text-align: center; margin-bottom: 30px;">
    <h1 style="color: #0077b5; margin-bottom: 10px;">Your LinkedIn Banners Are Ready! ✨</h1>
    <p style="font-size: 16px; color: #666;">Hi ${recipientName}, your custom LinkedIn banners have been generated!</p>
  </div>

  ${variationsHtml}

  ${specsHtml}

  ${tipsHtml}

  ${footerHtml}
</body>
</html>
`;

// Return output object
return [{
  json: {
    recipient_email: recipientEmail,
    recipient_name: recipientName,
    email_subject: 'Your LinkedIn Banners Are Ready! ✨',
    email_html: emailHtml,
    banner_urls: bannerUrls
  }
}];

